head.script:
scwin.screenId = "jldfil35601";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return String((String(String(dma_disclosureSchedule.get("calndDd")) == null ? '' : String(dma_disclosureSchedule.get("calndDd"))) === '' ? '' : String("yyyy-MM-dd").replace(/yyyy/g, String(String(dma_disclosureSchedule.get("calndDd"))).slice(0,4)).replace(/MM/g, String(String(dma_disclosureSchedule.get("calndDd"))).slice(4,6)).replace(/dd/g, String(String(dma_disclosureSchedule.get("calndDd"))).slice(6,8)).replace(/HH/g, String(String(dma_disclosureSchedule.get("calndDd"))).slice(8,10)).replace(/mm/g, String(String(dma_disclosureSchedule.get("calndDd"))).slice(10,12)).replace(/ss/g, String(String(dma_disclosureSchedule.get("calndDd"))).slice(12,14)))); } },
        { childId: "__rb2", fn: function () { return String(String(String(dma_disclosureSchedule.get("schdlContn")) == null ? '' : String(dma_disclosureSchedule.get("schdlContn"))).split(String.fromCharCode(10)).join('<br/>')); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil35601.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_ModSchedule_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_ModSchedule_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_ModSchedule_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.modSchedule()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil35601.btn_ModSchedule_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_DelSchedule_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_DelSchedule_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_DelSchedule_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.delSchedule()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil35601.btn_DelSchedule_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_Close_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_Close_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_Close_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.close()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil35601.btn_Close_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////



///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.modSchedule
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.modSchedule = function () {
    /* sdd-asis-lifecycle:begin fn_ModSchedule — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.win.setPageFrameSrc($c.win.getFrame(), '/jldfil35602/jldfil35602.xml') + "&calndDd=" + dma_disclosureSchedule.get("calndDd") + "&byddSeq=" + dma_disclosureSchedule.get("byddSeq") + "";
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.delSchedule
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.delSchedule = async function () {
    /* sdd-asis-lifecycle:begin fn_DelSchedule — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const _confirm = await $c.win.confirm("일정 '" + dma_disclosureSchedule.get("schdlTitle") + "'를\n삭제하시겠습니까?");
    if (!_confirm) {
        return;
    }
    $c.win.setPageFrameSrc($c.win.getFrame(), '/jldfil35602/jldfil35602.xml') + "&calndDd=" + dma_disclosureSchedule.get("calndDd") + "&byddSeq=" + dma_disclosureSchedule.get("byddSeq") + "";
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.close
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.close = function () {
    /* sdd-asis-lifecycle:begin fn_Close — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.win.closePopup();
    /* sdd-asis-lifecycle:end */
};
